    "type": "WS",
    "module": "Module10",
    "source": "ICAS AA | Workshop 4 | Slide pervasiveness | Paddington",
    "provider": "ICAS",
    "q": "<figure class=\"aa-source\"><img class=\"source-facsimile\" src=\"assets/aa-ws4-slide-paddington-q.png\" alt=\"Workshop 4 original source extract\" loading=\"eager\"></figure>",
